export const retentionMs = 48 * 60 * 60 * 1000;

const RETRYABLE_STATUSES = new Set([429, 502, 503, 504]);

// Delay to wait BEFORE the given attempt, in milliseconds. `attempt` is
// one-based: attempt 1 is the initial request and never waits. At most three
// attempts are permitted in total, so attempt 3 returns null (no further try).
export function retryDelay(status, attempt) {
  if (!RETRYABLE_STATUSES.has(status)) return null;
  if (attempt === 1) return 250;
  if (attempt === 2) return 500;
  return null;
}

