import { retentionMs } from './policy.mjs';

// Tenant IDs and keys may contain arbitrary punctuation, so a plain string
// join with a delimiter would let distinct identities collide (e.g.
// ("a|b", "c") vs ("a", "b|c")). Use a length-prefixed, injective encoding
// instead: each part is encoded as its UTF-8 length, a colon, then the value.
function identity(tenantId, key) {
  const t = String(tenantId);
  const k = String(key);
  return `${t.length}:${t}|${k.length}:${k}`;
}

export function createStore() {
  const entries = new Map();

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const record = entries.get(identity(tenantId, key));
      if (record === undefined) return { kind: 'miss' };

      // Expire exactly when now >= saved time + retentionMs.
      if (now >= record.savedAt + retentionMs) {
        entries.delete(identity(tenantId, key));
        return { kind: 'miss' };
      }

      if (record.fingerprint === fingerprint) {
        return { kind: 'hit', response: record.response };
      }
      return { kind: 'conflict' };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      entries.set(identity(tenantId, key), {
        fingerprint,
        response,
        savedAt: now,
      });
    },
  };
}

baseline.src/importer.mjs:
import { retryDelay } from './policy.mjs';

const CONFLICT_RESPONSE = { status: 409, body: { error: 'idempotency_conflict' } };

export async function importInvoice(request, deps) {
  const { tenantId, key, fingerprint, payload } = request;
  const { store, now, send, wait } = deps;

  // 1. Check for an existing record for this (tenantId, key) identity.
  //    A replay returns the original successful response without sending.
  const found = store.lookup({ tenantId, key, fingerprint, now: now() });
  if (found.kind === 'hit') return found.response;
  if (found.kind === 'conflict') return CONFLICT_RESPONSE;

  // 2. Miss: send, retrying only per the policy. At most three attempts.
  let response;
  for (let attempt = 1; ; attempt += 1) {
    try {
      response = await send({
        headers: { 'Idempotency-Key': key },
        body: payload,
      });
    } catch (error) {
      // A transport exception propagates without a retry or cache entry.
      throw error;
    }

    const delay = retryDelay(response.status, attempt);
    if (delay === null) break;
    await wait(delay);
  }

  // 3. Cache only successful (2xx) responses.
  if (response.status >= 200 && response.status < 300) {
    store.save({
      tenantId,
      key,
      fingerprint,
      response,
      now: now(),
    });
  }

  return response;
}

export async function importBatch(requests, deps) {
  const responses = [];
  for (const request of requests) {
    // Sequential: each item waits for the previous one to finish. An HTTP
    // failure response is recorded and processing continues; a thrown
    // transport exception propagates and stops the batch.
    responses.push(await importInvoice(request, deps));
  }
  return responses;
}

