import { retentionMs } from './policy.mjs';

// Tenant IDs and keys may contain arbitrary punctuation, so an unescaped
// delimiter join could map distinct identities onto the same entry. Use a
// nested map: outer keyed by tenantId, inner keyed by key.
function isExpired(entry, now) {
  return now >= entry.savedAt + retentionMs;
}

export function createStore() {
  const byTenant = new Map();

  function entriesFor(tenantId) {
    let inner = byTenant.get(tenantId);
    if (inner === undefined) {
      inner = new Map();
      byTenant.set(tenantId, inner);
    }
    return inner;
  }

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const inner = byTenant.get(tenantId);
      if (inner === undefined) return { kind: 'miss' };

      const entry = inner.get(key);
      if (entry === undefined) return { kind: 'miss' };

      if (isExpired(entry, now)) {
        // An expired entry behaves as a miss even if the fingerprint differs.
        inner.delete(key);
        return { kind: 'miss' };
      }

      if (entry.fingerprint !== fingerprint) return { kind: 'conflict' };
      return { kind: 'hit', response: entry.response };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      entriesFor(tenantId).set(key, { fingerprint, response, savedAt: now });
    },
  };
}

