import { retryDelay } from './policy.mjs';

const MAX_ATTEMPTS = 3;

function isSuccess(response) {
  return response !== null
    && typeof response === 'object'
    && typeof response.status === 'number'
    && response.status >= 200
    && response.status < 300;
}

function conflictResponse() {
  return { status: 409, body: { error: 'idempotency_conflict' } };
}

export async function importInvoice(request, deps) {
  const { tenantId, key, fingerprint, payload } = request;
  const { store, now, send, wait } = deps;

  const existing = store.lookup({ tenantId, key, fingerprint, now: now() });
  if (existing.kind === 'conflict') return conflictResponse();
  if (existing.kind === 'hit') return existing.response;

  let lastResponse;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    if (attempt > 1) {
      const delay = retryDelay(lastResponse.status, attempt);
      if (delay === null) break;
      await wait(delay);
    }

    // A transport exception must propagate without retry or cache entry.
    const response = await send({
      headers: { 'Idempotency-Key': key },
      body: payload,
    });

    if (isSuccess(response)) {
      store.save({ tenantId, key, fingerprint, response, now: now() });
      return response;
    }

    lastResponse = response;
  }

  return lastResponse;
}

export async function importBatch(requests, deps) {
  const responses = [];
  // Sequential processing: each item is fully resolved (including retries and
  // waits) before the next begins, reusing the same dependency object so the
  // shared store carries replay state across the batch.
  for (const request of requests) {
    // A non-success response is appended and processing continues; a thrown
    // transport exception propagates immediately and aborts the batch.
    const response = await importInvoice(request, deps);
    responses.push(response);
  }
  return responses;
}
